+      function matchesCategory(post) {
+        if (state.activeCategory === "All Posts") return true;
+        // Category pills are editorial; some posts are tagged as "General".
+        // Treat "General" as part of All Posts only.
+        return normalize(post.category) === normalize(state.activeCategory);
+      }
@@
       function init() {
@@
         // Initial render
         render();
+
+        // Close Flowbite dropdowns when pressing Escape (polish)
+        document.addEventListener("keydown", (e) => {
+          if (e.key !== "Escape") return;
+          for (const id of ["productsMenu", "resourcesMenu"]) {
+            const menu = document.getElementById(id);
+            if (!menu) continue;
+            menu.classList.add("hidden");
+          }
+        });
       }
*** End Patch
PATCH

